  ('441a99d9-73f3-56ee-8f28-9f7909a26d0f', '576a34df-e289-59ab-96e2-071d80bdd432', 'Morning Plate', null, 'Mixed greens served with scrambled eggs, avocado, cream cheese and toasted sourdough. Choice of cured meats or smoked salmon.', '21', null, null, false, null, 1),
  ('63559f33-73c6-53b7-89f3-232db61cff93', '576a34df-e289-59ab-96e2-071d80bdd432', 'Protein Plate', null, 'A fresh mixed greens salad, avocado, scrambled eggs, quinoa and roasted salmon.', '27', null, null, false, null, 2),
  ('d9056592-c497-5b97-9e36-b29532d34f68', '576a34df-e289-59ab-96e2-071d80bdd432', 'Chicken Club Sandwich', null, 'Crispy chicken schnitzel with melted cheese, pesto, homemade sauce, red onions, tomato and fresh arugula, served on toasted bread.', '16', null, null, false, null, 3),
  ('ef15d64e-bca0-5609-bbc1-101cf39f1da0', '576a34df-e289-59ab-96e2-071d80bdd432', 'Shakshuka', null, 'Poached eggs in a rich tomato and bell pepper sauce, finished with garlic, paprika and fresh herbs. Served with warm toasted sourdough bread.', '16', null, null, false, null, 4),
  ('6312e154-5ecf-54ba-8124-a20168e16ff3', '576a34df-e289-59ab-96e2-071d80bdd432', 'French Toast', null, 'Served with strawberry jam, Greek yogurt and agave syrup.', '15', null, null, false, null, 5),
  ('d45d44db-99b2-5f99-b221-59c627187bcb', '576a34df-e289-59ab-96e2-071d80bdd432', 'Oatmeal', null, 'Served with granola, fresh fruit and honey or maple syrup.', '12', null, null, false, null, 6),
  ('58f9049f-8ceb-51d4-ae73-1ffb996a3fb2', '8ab2cabd-6099-5a61-9042-457adc096c8e', 'Assorted Pkhali', null, 'Three kinds of vegetables — green beans, eggplant and beets — blended with a rich walnut paste, garlic, fresh herbs and traditional Georgian spices, served with homemade cornbread or bread.', '22', null, null, false, null, 1),
  ('6e51eb3c-0580-545c-aa8a-981d25f4cc2a', '8ab2cabd-6099-5a61-9042-457adc096c8e', 'Eggplant Rolls', null, 'Roasted eggplant filled with garlic-walnut sauce, topped with pomegranate. Georgian bread +3.', '19', null, null, false, null, 2),
  ('6729105f-aacd-5ffa-8fd4-2ee8394a497c', '8ab2cabd-6099-5a61-9042-457adc096c8e', 'The Georgian Salad', null, 'A fresh mix of tomatoes, cucumbers, onions, herbs and walnuts tossed in a traditional sunflower oil and vinegar dressing.', '18', null, null, false, null, 3),
  ('a92b49e5-0ef2-5204-b8c1-c2cb4594f12d', '8ab2cabd-6099-5a61-9042-457adc096c8e', 'Aromati’s Mix Salad', null, 'Fresh mixed greens with tomatoes, cucumbers, walnuts, herbs and red onions, finished with a house-made dressing. Contains pumpkin seeds.', '18', null, null, false, null, 4),
  ('9097c6c3-49d0-5de6-b353-8226463f04a6', '8ab2cabd-6099-5a61-9042-457adc096c8e', 'Greek Salad', null, 'A fresh mix of cucumbers, tomatoes, red onions, bell peppers, Kalamata olives and feta cheese.', '19', null, null, false, null, 5),
  ('6fcf8155-c828-5ff0-af41-45e4409b417e', '8ab2cabd-6099-5a61-9042-457adc096c8e', 'Arugula Salad with Goat Cheese', null, 'A fresh blend of arugula, strawberries, herbs and red onions, finished with oil and a house-made garlic dressing. Contains honey and pumpkin seeds.', '19', null, null, false, null, 6),
  ('d5ed13b4-aa88-51dc-acde-b6dc611f6aba', '37a80aea-cf89-5030-aeed-123716f679a8', 'Adjaruli Khachapuri', null, 'A boat-shaped khachapuri with cheese, topped with an egg yolk and butter.', '19', null, null, false, null, 1),
  ('3aba55a7-d4e3-5758-9882-382459a4ff05', '37a80aea-cf89-5030-aeed-123716f679a8', 'Khachapuri with Arugula', null, 'Freshly baked open-face Georgian bread topped with melted cheese, fresh arugula and our house sauce.', '19', null, null, false, null, 2),
  ('68bb88ae-812d-5cd9-b922-03307b8098b5', '37a80aea-cf89-5030-aeed-123716f679a8', 'Imeruli Khachapuri', null, 'Round-shaped khachapuri with a cheese filling.', '19', null, null, false, null, 3),
  ('3035c090-5738-5d99-a99d-dcacb95640d8', '37a80aea-cf89-5030-aeed-123716f679a8', 'Lobiani', null, 'Traditional bean-filled homemade bread.', '18', null, null, false, null, 4),
  ('62f55017-475b-53b0-8839-a285f867454f', '37a80aea-cf89-5030-aeed-123716f679a8', 'Penovani Khachapuri', null, 'Puff pastry stuffed with blended cheese.', '17', null, null, false, null, 5),
  ('fb43648c-74c7-56a6-9190-43de4919d10e', '37a80aea-cf89-5030-aeed-123716f679a8', 'Kubdari', null, 'A round-shaped bread filled with seasoned chopped beef and pork.', '22', null, null, false, null, 6),
  ('7ff4b7ea-01df-5283-9cef-294a29b50a67', '37a80aea-cf89-5030-aeed-123716f679a8', 'Penovani with Spinach', null, 'Puff pastry stuffed with blended cheese and spinach.', '18', null, null, false, null, 7),
  ('dc28aa51-9c44-5d07-ba20-ced0efaf2692', '37a80aea-cf89-5030-aeed-123716f679a8', 'Puri Beef Burger', null, 'Juicy beef patty, fresh vegetables, cheese and signature sauce served in freshly baked Georgian puri.', '19', null, null, false, null, 8),
  ('af366ffe-34b8-5980-80ee-f07125fd9ed3', '37a80aea-cf89-5030-aeed-123716f679a8', 'Georgian Puri', null, 'Freshly baked traditional Georgian bread, served hot with house-made Georgian ajika, a spicy pepper paste.', '8', null, null, false, null, 9),
  ('a20350a8-4325-5388-8a53-9273ffdbd2e0', 'f00ce704-100e-5c30-821b-bc775899ed8d', 'Khinkali', null, 'Hand-folded Georgian dumplings filled with a blend of beef and pork in a rich, savory broth. Three per serving.', '14', null, null, false, null, 1),
  ('a37f1429-031f-5e71-a7a2-64ea3289514a', 'f00ce704-100e-5c30-821b-bc775899ed8d', 'Kvarabia', null, 'Megruli cheese dumplings, served with homemade yogurt. Three per serving.', '14', null, null, false, null, 2),
  ('c8db0960-e972-5199-bbbd-ce7df764265e', 'f00ce704-100e-5c30-821b-bc775899ed8d', 'Tolma', null, 'Seasoned ground beef and pork wrapped in grape leaves, served with a creamy garlic sauce.', '17', null, null, false, null, 3),
  ('e343b4e7-7bc6-5146-b701-9ab789c991a6', 'f00ce704-100e-5c30-821b-bc775899ed8d', 'Lobio', null, 'Slow-cooked traditional Georgian beans with special seasonings and fresh herbs, served with house-marinated vegetables and freshly baked bread.', '21', null, null, false, null, 4),
