  ('0ed0836e-7536-513b-b072-842e16d298c8', '0c5e8156-4ca2-527d-8aa3-0bb0f42e8624', 'Lentil Soup', null, 'Slow-simmered lentils, mixed greens, garlic and ground red pepper.', '14', null, null, false, null, 4),
  ('55f33766-c2d6-5e8d-a0e3-a83d8a10585d', 'f810779f-a24c-5109-80a5-f89b5dabdffe', 'Honey Cake', null, 'Delicate honey-infused cake layers filled with silky caramel buttercream.', '10', null, null, false, null, 1),
