  ('5506e480-8329-5923-a9be-fb51747613ff', 'ef721aad-8ca3-5c7e-aecc-f33a25579e58', 'Sparkling Grape Cocktail', null, 'Sparkling wine, Prosecco Brut DOC, grape juice, lime.', '17', null, null, false, null, 4),
  ('3147a50f-7b7a-5945-831a-bd776470c05a', 'ef721aad-8ca3-5c7e-aecc-f33a25579e58', 'Aromati’s Limoncello Spritz', null, 'Prosecco Brut DOC, Amalfi Coast organic limoncello, fresh lemon.', '18', null, null, false, null, 5),
  ('9c865144-2620-51d0-8bfa-1701a013b67e', 'ef721aad-8ca3-5c7e-aecc-f33a25579e58', 'Pomegranate Spritz', null, 'Aperol, prosecco, pomegranate juice.', '18', null, null, false, null, 6),
  ('b9803a07-8af2-5c70-9d79-8bbbef1eb662', 'ef721aad-8ca3-5c7e-aecc-f33a25579e58', 'The Bellini', null, 'White peach purée and Prosecco Brut DOC.', '17', null, null, false, null, 7),
  ('7f04a7ef-62e0-567d-8229-c166a92e3b2b', 'ef721aad-8ca3-5c7e-aecc-f33a25579e58', 'Mimosa', null, 'Orange juice and Prosecco Brut DOC.', '17', null, null, false, null, 8),
  ('938d3601-273a-5e34-b24c-d5660721b551', 'ef721aad-8ca3-5c7e-aecc-f33a25579e58', 'Espresso Martini', null, 'Kahlúa coffee liqueur, fresh espresso and coffee syrup.', '17', null, null, false, null, 9),
  ('93b47bdb-e726-5b41-b262-1c1c85f0af0d', 'baa440a4-62dd-5745-a0f4-0a41110a01f8', 'Kisi', '2020', 'Kakheti, Vellino. Dry amber wine with ripe apricot and peach, floral hints and a touch of citrus.', '18', null, null, false, null, 1),
  ('9ac05b54-2cf3-542a-bc7b-80e7331795d8', 'baa440a4-62dd-5745-a0f4-0a41110a01f8', 'Saperavi', '2023', 'Nadelebi Winery, Kakheti. Dry red wine with rich aromas of dark berries, notably black cherry and blackberry, with hints of plum and floral notes.', '18', null, null, false, null, 2),
  ('c534ae8b-033e-5755-b467-019643c89532', 'baa440a4-62dd-5745-a0f4-0a41110a01f8', 'Sopromadze', '2022', 'Tsitska · Tsolikouri · Krakhuna, Kakheti. Dry white wine with crisp acidity and fresh citrus notes.', '18', null, null, false, null, 3),
  ('3f613a0a-108b-51a3-9df5-c3e2067c6ef3', 'baa440a4-62dd-5745-a0f4-0a41110a01f8', 'Mtsvane', '2020', 'Kakheti. Dry amber wine with primary aromas of citrus fruits such as lemon, lime and green apple, with notes of tropical fruit.', '17', null, null, false, null, 4),
  ('d85c7d47-5304-5b75-94b3-68003c3e8bb6', 'baa440a4-62dd-5745-a0f4-0a41110a01f8', 'Rkatsiteli', '2023', 'Khvitsia Wine, Kardenakhi — Kakheti. Dry white wine with lively acidity and floral hints.', '17', null, null, false, null, 5),
  ('270cf64b-0554-50de-bc0c-944a1bbb1a75', 'baa440a4-62dd-5745-a0f4-0a41110a01f8', 'Mtsvane', '2022', 'Single vineyard Kakheti, Manavi Wines. Dry white wine with crisp green apple, juicy pear and delicate floral notes.', '16', null, null, false, null, 6),
  ('1b29ba10-a0ba-5dc1-8bba-45fcced4249e', 'be178dde-3b22-53d9-a88e-9aea7042eb22', 'Goruli Mtsvane', null, 'Dry white, Kartli — known for its light straw color with green tones, with intense notes of pineapple, lemon and feijoa.', '19', null, null, false, null, 1),
  ('c5007111-3974-53e6-80c4-39f0a1ef670e', 'be178dde-3b22-53d9-a88e-9aea7042eb22', 'Chinuri', null, 'Dry white, Kartli — pale straw-colored, with strongly expressed orange and pear tones. Sparkling acidity gives the wine a special character.', '18', null, null, false, null, 2),
  ('e73844af-e931-5453-a9d6-ee52b72c070b', 'be178dde-3b22-53d9-a88e-9aea7042eb22', 'Kisi Qvevri', null, 'Dry amber qvevri wine, Kakheti — honey and cinnamon aromas with notes of yellow and dried fruits.', '17', null, null, false, null, 3),
  ('37498d05-4bed-593a-91ae-aa4fef1c0f30', 'be178dde-3b22-53d9-a88e-9aea7042eb22', 'Rkatsiteli Qvevri', null, 'Dry amber qvevri wine, Kakheti — pronounced spicy aromas with hints of honey and tobacco.', '17', null, null, false, null, 4),
  ('e74e1da5-2c45-5a8d-a6cd-af44c58f3356', 'be178dde-3b22-53d9-a88e-9aea7042eb22', 'Tsolikouri', null, 'Imereti dry white wine, with delicate aromas of yellow and white fruits.', '16', null, null, false, null, 5),
  ('b2bd7d94-d683-590f-afc3-77b2f4ca5f15', 'be178dde-3b22-53d9-a88e-9aea7042eb22', 'Tvishi', null, 'Naturally semi-sweet, Lechkhumi — yellow and tropical fruit aromas with citrus undertones.', '16', null, null, false, null, 6),
  ('db1024bd-462f-5cdd-b669-012bf3d4d246', 'be178dde-3b22-53d9-a88e-9aea7042eb22', 'Pirosmani White', null, 'Kakheti — balanced, fruity profile with notes of ripe white fruit, pear, melon and citrus.', '15', null, null, false, null, 7),
  ('78cebe9b-7e44-50f8-83ed-48552379f01c', 'be178dde-3b22-53d9-a88e-9aea7042eb22', 'Brut', null, 'Sparkling wine, Imereti · Kakheti · Kartli — known for its pale straw color, high acidity, and notes of citrus, pear and stone fruits.', '15', null, null, false, null, 8),
  ('e70c24f8-40ff-5fc9-97bb-517761e1e271', 'c1c26fc2-cf3e-573f-b09e-ca13e4924f79', 'Saperavi Legend', null, 'Dry red, Kartli — aged in oak barrels, this elegant red reveals layered aromas of red and dark berries, with a smooth, well-balanced finish.', '20', null, null, false, null, 1),
  ('c9e658e9-19e6-570b-b390-7abc91b15d06', 'c1c26fc2-cf3e-573f-b09e-ca13e4924f79', 'Saperavi Reserve', null, 'Premium red wine, Kakheti — complex flavors of black fruit (plum, blackberry, cherry), spice and vanilla. Often aged in oak, resulting in a rich, velvety finish.', '18', null, null, false, null, 2),
  ('5058412e-97c4-57a9-95f6-2674156958ac', 'c1c26fc2-cf3e-573f-b09e-ca13e4924f79', 'Saperavi Qvevri', null, 'Dry red qvevri wine from Kakheti — aromas of dried black plum, cherry and blackberry.', '17', null, null, false, null, 3),
  ('d4191b99-3e5d-5d98-97ec-827e7d7e8a05', 'c1c26fc2-cf3e-573f-b09e-ca13e4924f79', 'Shavkapito Merlot', null, 'Dry red, Kartli — crafted in the traditional Georgian barrel-aging method. Deep ruby in color, with vibrant red-fruit aromas of cherry and plum.', '18', null, null, false, null, 4),
  ('7b52ea7c-ca19-5649-bd26-4e256cd00ad7', 'c1c26fc2-cf3e-573f-b09e-ca13e4924f79', 'Mukuzani', null, 'Dry red wine from Kakheti — rich dark berry aromas with hints of oak and spice.', '18', null, null, false, null, 5),
  ('cd6ea824-d03b-5036-b59e-8138a8f33ff0', 'c1c26fc2-cf3e-573f-b09e-ca13e4924f79', 'Kindzmarauli', null, 'Red semi-sweet wine, with a rich flavor of berries, plum and rose petals.', '18', null, null, false, null, 6),
  ('89fcf9b6-3e68-56e3-8ca5-1203ca8623a9', 'c1c26fc2-cf3e-573f-b09e-ca13e4924f79', 'Saperavi Rosé', null, 'Dry rosé — produced from the Saperavi grape variety, characterized by a fairly high acidity.', '16', null, null, false, null, 7),
  ('265d561e-23d3-52cc-9da9-e7e2f195c8c1', 'b4b87b25-b782-523d-8ccf-4fcb26e58921', 'Barbera d’Asti', null, 'DOCG “Runc”, Piedmont — rich with floral tones of iris and rose, with hints of undergrowth, raspberry and plum.', '15', null, null, false, null, 1),
  ('e4175bd7-9ec9-57f1-b2ef-a6825d42776d', 'b4b87b25-b782-523d-8ccf-4fcb26e58921', 'Friularo', null, 'Ambasciatore, Veneto — an elegant red wine with an intense aroma, featuring spicy notes, violet and sour cherry.', '17', null, null, false, null, 2),
  ('541f1c3f-13ab-5d10-968e-53bfe11a2ac3', 'b4b87b25-b782-523d-8ccf-4fcb26e58921', 'Prosecco Brut', null, 'DOC — Castello di Roncade, Veneto. Very fine and elegant, floral and fruity, with hints of acacia flower, green apple and almonds. Dry, fresh, lively on the palate.', '16', null, null, false, null, 3),
  ('738eb521-0f4c-566e-bd43-585454bee99d', 'b4b87b25-b782-523d-8ccf-4fcb26e58921', 'Chardonnay', null, 'Muzic Collio — structured and fresh, with hints of apricot and green apple. Intense and refined, with a robust finish.', '18', null, null, false, null, 4),
  ('2cd251f2-db1e-5798-b17c-45581ad38b22', 'b4b87b25-b782-523d-8ccf-4fcb26e58921', 'Sauvignon Blanc', null, 'Alto Adige, Kossler — elegant and balanced, crisp acidity and a flowery aroma, with notes of white peaches and grapefruit, tropical fruit and citrus.', '18', null, null, false, null, 5),
  ('93148e6b-02bf-5bfc-bc9b-5a2ba590589b', 'b4b87b25-b782-523d-8ccf-4fcb26e58921', 'Falanghina del Sannio', null, 'DOP — Fontanavecchia, Campania. Aromatic notes of ripe apple and citrus blossom, with hints of pear, peach and crushed stone. Crisp, with a refreshing structure.', '18', null, null, false, null, 6),
  ('9362922a-0e16-56ea-9df2-da761f7c03c5', 'b4b87b25-b782-523d-8ccf-4fcb26e58921', 'Georgian Lager — Kazbegi', null, null, '8.50', null, null, false, null, 7),
  ('a9437669-db42-5f3b-9ef4-3a27a23d2e09', 'b4b87b25-b782-523d-8ccf-4fcb26e58921', 'Corona Extra', '12 oz', null, '6.50', null, null, false, null, 8),
  ('adfb1861-36c6-5676-8811-8a4d3522b670', 'b4b87b25-b782-523d-8ccf-4fcb26e58921', 'Heineken', '12 oz', null, '6', null, null, false, null, 9),
  ('db5c44d1-763a-58db-b03a-d63fac16ef36', '7e57b1ba-3e8d-5b12-b7ef-5356da011928', 'Aromati’s Charcuterie & Cheese Board', null, 'A selection of cured meats and artisan cheeses, served with fresh fruit, olives, nuts, jam and crackers.', null, null, null, true, null, 1),
  ('dcd8297f-a8b5-50b4-9a6b-aa99c25d4b19', '7e57b1ba-3e8d-5b12-b7ef-5356da011928', 'Cheese Board', null, 'Chef’s selection of artisan cheeses, served with croutons, fresh fruit, nuts and jam.', null, null, null, true, null, 2);
