insert into public.site_copy (key, page, section, label, help, value, max_length, sort_order) values
  ('hero.eyebrow', 'index', 'Hero', 'Small line above the name', null, 'Murray Hill · Manhattan', null, 10),
  ('hero.desc', 'index', 'Hero', 'Opening sentence', 'Starting a new line here puts one on the page.', E'Two floors on East 34th Street where Georgian cooking,\nnatural wine and coffee share one table.', null, 20),
  ('hero.ctaPrimary', 'index', 'Hero', 'First button', null, 'See the Menus', null, 30),
  ('hero.ctaSecondary', 'index', 'Hero', 'Second button', null, 'The Wine Bar', null, 40),
  ('story.label', 'index', 'The Idea', 'Section tag', null, 'The Idea', null, 50),
  ('story.headline', 'index', 'The Idea', 'Headline', null, 'Georgian cooking for a Manhattan morning.', 72, 60),
  ('story.lead', 'index', 'The Idea', 'Opening paragraph', 'Put *asterisks* around words to set them in italic.', 'Aromati, from the Georgian word for *aroma*, is a bi-level café and wine bar in Murray Hill, where American coffee culture meets the oldest food and wine traditions in Europe.', null, 70),
  ('story.body', 'index', 'The Idea', 'Second paragraph', null, 'Downstairs, an open kitchen and coffee bar move at the pace of the city: espresso pulled, matcha whisked, khachapuri blistering in the oven. Upstairs, the room slows down into burgundy walls, tufted leather, cane and oak, and low globe light, a dining room and wine bar built for long evenings.', null, 80),
  ('story.quote', 'index', 'The Idea', 'Pull quote', null, 'Georgia has been making wine for eight thousand years. We think it belongs at the table, whatever the occasion.', null, 90),
  ('kitchen.label', 'index', 'The Kitchen', 'Section tag', null, 'The Kitchen', null, 100),
  ('kitchen.headline', 'index', 'The Kitchen', 'Headline', null, 'Bread, cheese, and broth: a few staples of the Georgian table.', 72, 110),
  ('kitchen.lede', 'index', 'The Kitchen', 'Paragraph under the headline', null, 'Everything comes out of the open kitchen on the ground floor. Khachapuri is blistered to order and khinkali is pleated by hand.', null, 120),
  ('kitchen.reelLabel', 'index', 'The Kitchen', 'Caption above the photo strip', null, 'A few plates', null, 130),
  ('kitchen.reelNote', 'index', 'The Kitchen', 'Small note beside the caption', null, 'photographed in the room', null, 140),
  ('cafe.label', 'index', 'The Café', 'Section tag', null, 'The Café', null, 150),
  ('cafe.headline', 'index', 'The Café', 'Headline', null, 'Downstairs runs on espresso.', 72, 160),
  ('cafe.lede', 'index', 'The Café', 'Paragraph under the headline', null, 'The ground floor is a New York coffee bar with espresso drinks, matcha, and pastries for the morning.', null, 170),
  ('cafe.card1.title', 'index', 'The Café', 'Card 1 — drink', null, 'Tiramisu Latte', null, 180),
  ('cafe.card1.note', 'index', 'The Café', 'Card 1 — description', null, 'mascarpone cream, cocoa, a ladyfinger on top', null, 190),
  ('cafe.card2.title', 'index', 'The Café', 'Card 2 — drink', null, 'Maple Syrup Iced Latte', null, 200),
  ('cafe.card2.note', 'index', 'The Café', 'Card 2 — description', null, 'topped with silky maple cold foam', null, 210),
  ('cafe.card3.title', 'index', 'The Café', 'Card 3 — drink', null, 'Fruit Matchas', null, 220),
  ('cafe.card3.note', 'index', 'The Café', 'Card 3 — description', null, 'strawberry, mango & blueberry, layered over ice', null, 230),
  ('cafe.card4.title', 'index', 'The Café', 'Card 4 — drink', null, 'The Classics', null, 240),
  ('cafe.card4.note', 'index', 'The Café', 'Card 4 — description', null, 'flat whites & cappuccinos, poured properly', null, 250),
  ('cafe.cta', 'index', 'The Café', 'Sentence above the button', null, 'The drinks menu includes espresso, matcha, chai, smoothies, and cold drinks.', null, 260),
  ('cafe.ctaButton', 'index', 'The Café', 'Button', null, 'See the Drinks Menu', null, 270),
  ('wine.label', 'index', 'The Wine Bar', 'Section tag', null, 'The Wine Bar', null, 280),
  ('wine.headline', 'index', 'The Wine Bar', 'Headline', null, 'A wine list shaped by Georgia.', 72, 290),
  ('wine.lede', 'index', 'The Wine Bar', 'Paragraph under the headline', null, 'Upstairs, the list brings together qvevri ambers, Saperavi, natural wines, and a short European selection. Wines are available by the glass or bottle, with pairings for the table.', null, 300),
  ('wine.note1.title', 'index', 'The Wine Bar', 'Note 1 — title', null, 'Amber', null, 310),
  ('wine.note1.text', 'index', 'The Wine Bar', 'Note 1 — description', null, 'Amber wines bring notes of honey, spice, dried fruit, and citrus.', null, 320),
  ('wine.note2.title', 'index', 'The Wine Bar', 'Note 2 — title', null, 'Saperavi', null, 330),
  ('wine.note2.text', 'index', 'The Wine Bar', 'Note 2 — description', null, 'Saperavi is a Georgian red with dark berry, plum, and cherry notes.', null, 340),
  ('wine.note3.title', 'index', 'The Wine Bar', 'Note 3 — title', null, 'Qvevri', null, 350),
  ('wine.note3.text', 'index', 'The Wine Bar', 'Note 3 — description', null, 'The list includes qvevri wines in both amber and red styles.', null, 360),
  ('wine.hours', 'index', 'The Wine Bar', 'Small line about the room', null, 'Second floor · wine bar', null, 370),
  ('wine.ctaButton', 'index', 'The Wine Bar', 'Button', null, 'Read the Wine List', null, 380),
  ('gallery.label', 'index', 'The Room', 'Section tag', null, 'The Room', null, 390),
  ('gallery.headline', 'index', 'The Room', 'Headline', null, 'Cane, leather, burgundy — and light that lingers.', 72, 400),
  ('visit.label', 'index', 'Visit', 'Section tag', null, 'Visit', null, 410),
  ('visit.headline', 'index', 'Visit', 'Headline', 'Starting a new line here puts one on the page.', E'Come say hello,\nMurray Hill.', 72, 420),
  ('food.label', 'food', 'Food menu', 'Section tag', null, 'The Kitchen', null, 430),
  ('food.headline', 'food', 'Food menu', 'Page title', null, 'The Food Menu', 32, 440),
  ('food.lede', 'food', 'Food menu', 'Paragraph under the title', null, 'Everything comes out of the open kitchen on the ground floor. Khachapuri is blistered to order and khinkali is pleated by hand. Served all day.', null, 450),
  ('food.footNote', 'food', 'Food menu', 'Note at the foot of the menu', null, '…and salads, stews, toast & sweets in between.', null, 460),
  ('food.footButton', 'food', 'Food menu', 'Button at the foot of the menu', null, 'Come Hungry', null, 470),
  ('drinks.label', 'drinks', 'Drinks menu', 'Section tag', null, 'The Café', null, 480),
